function ipName(city,reg,cc,country){const s=((reg||'')+' '+(city||'')).toLowerCase();if(/^(KR|South Korea|Korea)/i.test(cc||country||'')){const m=KR_REG.find(k=>s.includes(k[0]));return m?m[1]:'국내'}return country||cc||''}
async function ipAsk(ip){const O={credentials:'omit',referrerPolicy:'no-referrer',cache:'no-store'},ctl=()=>({...O,signal:AbortSignal.timeout?AbortSignal.timeout(7000):undefined}),P=encodeURIComponent(ip);
  try{const r=await (await fetch('https://ipwho.is/'+P+'?fields=success,city,region,country,country_code',ctl())).json();if(r&&r.success){const n=ipName(r.city,r.region,r.country_code,r.country);if(n)return n}}catch(e){}
  try{const r=await (await fetch('https://ipapi.co/'+P+'/json/',ctl())).json();if(r&&!r.error){const n=ipName(r.city,r.region,r.country_code,r.country_name);if(n)return n}}catch(e){}
  return null}
