  const ips=[...new Set([...document.querySelectorAll('.ipCity')].map(e=>e.dataset.ip))],Q=[];ips.forEach(ip=>{if(ipLocal(ip))return show(ip,'내부망');const c=C[ip];if(c&&now-c[1]<6048e5)show(ip,c[0]);else Q.push(ip)});
