/* 창작 공방: 16칸 도트 그림. 서버(art_top, art_add, art_del) 저장 */
const ART_PAL=['#ffffff','#111827','#ef4444','#f97316','#fbbf24','#22c55e','#0ea5e9','#2563eb','#a855f7','#ec4899','#92400e','#94a3b8'];
let ART_L=[],ART_IMGS=[];const PT={g:null,c:1};
function artImg(d){const c=document.createElement('canvas');c.width=c.height=16;const X=c.getContext('2d');[...d].forEach((k,i)=>{X.fillStyle=ART_PAL[parseInt(k,16)]||'#fff';X.fillRect(i%16,i/16|0,1,1)});return c}
async function artLoad(){try{const r=await DB.rpc('art_top');ART_L=Array.isArray(r)?r:[];ART_IMGS=ART_L.slice(0,7).map(a=>artImg(a.data))}catch(e){ART_L=[];ART_IMGS=[];throw e}}
function showPaint(){PT.g=Array(256).fill(0);PT.c=1;openM('<h3>🎨 도트 그림 그리기</h3><div id="ptG" style="display:grid;grid-template-columns:repeat(16,1fr);width:min(100%,320px);margin:0 auto;border:2px solid #111827;touch-action:none;background:#fff">'+PT.g.map((v,i)=>'<div data-i="'+i+'" style="aspect-ratio:1;background:#fff;box-shadow:inset 0 0 0 .5px #e2e8f0"></div>').join('')+'</div><div style="display:flex;flex-wrap:wrap;gap:4px;justify-content:center;margin:8px 0">'+ART_PAL.map((c,i)=>'<button onclick="PT.c='+i+';ptMark()" id="ptC'+i+'" style="width:26px;height:26px;border-radius:50%;background:'+c+';border:2px solid #cbd5e1;cursor:pointer" aria-label="색 '+(i+1)+'"></button>').join('')+'</div><input id="ptN" class="xin" maxlength="12" placeholder="이름 (선택)" onkeydown="event.stopPropagation()" value="'+esc(FRIEND?FRIEND.short:GUEST.name||'')+'"><div class="xcol" style="margin-top:6px"><button class="xb big" onclick="ptSend()">벽에 걸기</button><button class="xb" onclick="showPaint()">지우고 다시</button></div>');ptMark();const G=$('#ptG'),draw=e=>{const el=document.elementFromPoint(e.clientX,e.clientY);if(!el||el.dataset.i==null)return;e.preventDefault();PT.g[+el.dataset.i]=PT.c;el.style.background=ART_PAL[PT.c]};let dn=false;G.addEventListener('pointerdown',e=>{dn=true;G.setPointerCapture&&G.releasePointerCapture&&0;draw(e)});G.addEventListener('pointermove',e=>{if(dn)draw(e)});G.addEventListener('pointerup',()=>dn=false);G.addEventListener('pointerleave',()=>dn=false)}
function ptMark(){ART_PAL.forEach((_,i)=>{const b=$('#ptC'+i);if(b)b.style.borderColor=i==PT.c?'#111827':'#cbd5e1'})}
async function ptSend(){if(PT.g.every(v=>!v))return toast('먼저 그려 주세요.');const n=($('#ptN').value||'').trim();try{const r=await DB.rpc('art_add',{p_name:n,p_data:PT.g.map(v=>v.toString(16)).join('')});if(!r||!r.ok)return toast(r&&r.err=='rate'?'잠시 뒤에 다시 걸어 주세요.':'걸지 못했어요.');toast('벽에 걸었어요! 🖼');await artLoad();showArt()}catch(e){toast('공방 서버 준비 중이에요.')}}
async function showArt(){openM('<h3>🖼 공방 작품</h3><p style="font-size:12px;opacity:.7">불러오는 중…</p>');try{await artLoad()}catch(e){openM('<h3>🖼 공방 작품</h3><div class="cd">공방 서버 준비 중이에요.</div>');return}const ad=DB.admin();openM('<h3>🖼 공방 작품</h3>'+(ART_L.length?'<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(84px,1fr));gap:8px">'+ART_L.map(a=>'<figure style="margin:0;text-align:center"><img src="'+artImg(a.data).toDataURL()+'" alt="'+esc(a.name)+'의 그림" style="width:100%;image-rendering:pixelated;border:2px solid #3f2a1c;background:#fff"><figcaption style="font-size:11px">'+esc(a.name)+' <button class="xb" style="padding:0 4px" onclick="artLike('+Number(a.id)+')">❤️ '+Number(a.likes||0)+'</button>'+(ad?' <button class="xb r" style="padding:0 4px" onclick="artDel('+Number(a.id)+')">지우기</button>':'')+'</figcaption></figure>').join('')+'</div>':'<div class="cd">아직 작품이 없어요. 첫 작품을 그려 보세요!</div>')+'<div class="xcol" style="margin-top:8px"><button class="xb" onclick="showPaint()">🎨 나도 그리기</button></div>')}
async function artLike(id){try{const r=await DB.rpc('art_like_add',{p_id:id,p_tok:mvTok()});if(r&&r.ok)showArt();else toast('좋아요를 남기지 못했어요.')}catch(e){toast('공방 서버 준비 중이에요.')}}
async function artDel(id){try{const r=await DB.rpc('art_del',{p_id:id});if(!r||!r.ok)return toast('운영자만 지울 수 있어요.');toast('지웠어요.');showArt()}catch(e){toast(dbErr(e))}}
/* 같이 돌아다니기: Supabase Realtime Broadcast. 위치는 저장하지 않음. 이름은 서버(presence_*)가 정해 준 것만 표시 */
const RT_EM=['👋','😂','🍊','👍','❤️','🎉','😮','😭'];
/* 간단 대화: 정해 둔 문장만 주고받음 (번호만 보내서 아무 글이나 퍼지지 않음) */const RT_QC=['안녕하세요! 👋','반가워요 😄','같이 다녀요!','이쪽으로 따라오세요','잠깐만 기다려 주세요','어디로 갈까요?','좋아요 👍','고마워요!','미안해요 🙏','재밌다 ㅋㅋ','배고프다 🍚','여기 예쁘다 📸','먼저 가 볼게요','잘 가요 👋','또 만나요!','네!','아니요'];let QC_AT=0;
function rtQc(i){if(!RT_QC[i])return;const n=Date.now();if(n-QC_AT<1200)return toast('조금 천천히 말해 주세요.');QC_AT=n;RT.mySay=RT_QC[i];RT.sayAt=n;if(RT.on&&RT.pid&&!RT.hide&&RT.map)rtBc(RT.map,'qc',{i:RT.pid,q:i});closeM()}
const qcUi=()=>'<b style="font-size:13px">💬 말 걸기</b><div style="display:flex;flex-wrap:wrap;gap:5px;margin:6px 0">'+RT_QC.map((q,i)=>'<button class="xb" style="font-size:12px;padding:5px 8px" onclick="rtQc('+i+')">'+esc(q)+'</button>').join('')+'</div>';
const RT={fr:'',mySay:'',sayAt:0,ws:null,on:false,pid:'',name:'',owner:false,ref:1,map:null,peers:{},all:{},names:{},hide:false,last:'',sentAt:0,emAt:0,myEm:null,ask:new Set(),hb:0};
