const rtTopic=m=>'realtime:bsw_'+m;
function rtSend(topic,event,payload){if(RT.ws&&RT.ws.readyState==1)RT.ws.send(JSON.stringify({topic,event,payload,ref:String(RT.ref++)}))}
function rtJoin(m){rtSend(rtTopic(m),'phx_join',{config:{broadcast:{self:false,ack:false},presence:{key:''},private:false}})}
function rtBc(m,event,payload){rtSend(rtTopic(m),'broadcast',{type:'broadcast',event,payload})}
function rtLabel(pid){return RT.names[pid]&&RT.names[pid].name||'손님 '+String(pid).slice(0,4).toUpperCase()}
async function rtNames(){const L=[...RT.ask].slice(0,30);if(!L.length)return;L.forEach(p=>RT.ask.delete(p));try{const r=await DB.rpc('presence_names',{p_ids:L});if(r)Object.assign(RT.names,r);L.forEach(p=>{if(!RT.names[p])RT.names[p]={name:'',owner:false}});rtBtn()}catch(e){}}
function rtSeen(pid){if(!RT.names[pid])RT.ask.add(pid)}
function rtOk(p){return p&&typeof p.i=='string'&&/^[0-9a-f]{12}$/.test(p.i)&&p.i!=RT.pid}
function rtMsg(m){if(m.event!='broadcast'||!m.payload||!m.payload.payload)return;const ev=m.payload.event,p=m.payload.payload;if(!rtOk(p))return;RT.all[p.i]=Date.now();rtSeen(p.i);if(ev=='hi')return rtBtn();if(m.topic!=rtTopic(RT.map))return;if(ev=='bye'){delete RT.peers[p.i];return}const P=RT.peers[p.i]||(Object.keys(RT.peers).length<30?RT.peers[p.i]={x:p.x,y:p.y,tx:p.x,ty:p.y}:null);if(!P)return;P.seen=Date.now();if(ev=='pos'&&Number.isInteger(p.x)&&Number.isInteger(p.y)&&p.x>=0&&p.y>=0&&p.x<80&&p.y<80){P.tx=p.x;P.ty=p.y;P.d=[0,1,2,3].includes(p.d)?p.d:0;P.lk=Number.isInteger(p.l)&&G_LOOKS[p.l]?p.l:0}else if(ev=='lk'&&p.t==RT.pid&&[0,1,2,3].includes(p.d)){if(!SIT&&!busy&&!mv&&!modal){dir=p.d;rtPos(true)}const n0=Date.now();if(!RT.lkT||n0-RT.lkT>4000){RT.lkT=n0;toast('👋 '+rtLabel(p.i)+' 님이 말을 걸었어요.')}}else if(ev=='em'&&Number.isInteger(p.e)&&RT_EM[p.e]){P.em=RT_EM[p.e];P.emT=Date.now()}else if(ev=='qc'&&Number.isInteger(p.q)&&RT_QC[p.q]){P.say=RT_QC[p.q];P.sayT=Date.now()}else if(ev=='sa'&&Number.isInteger(p.s)&&RT.names[p.i]&&RT.names[p.i].fr=='ck'&&(TX.ck||[])[p.s]){P.say=TX.ck[p.s][0];P.sayT=Date.now()}}
function rtConnect(){if(RT.ws&&RT.ws.readyState<2)return;try{const u=DBCFG.url.replace(/^http/,'ws')+'/realtime/v1/websocket?apikey='+encodeURIComponent(DBCFG.key)+'&vsn=1.0.0';const ws=new WebSocket(u);RT.ws=ws;ws.onopen=()=>{RT.on=true;rtJoin('lobby');if(RT.map)rtJoin(RT.map);rtHi();rtPos(true)};ws.onmessage=e=>{try{rtMsg(JSON.parse(e.data))}catch(_){}};ws.onclose=()=>{RT.on=false;setTimeout(rtConnect,8000)};ws.onerror=()=>{}}catch(e){}}
function rtHi(){if(RT.pid&&!RT.hide)rtBc('lobby','hi',{i:RT.pid})}
function rtPos(force){if(!RT.on||!RT.pid||RT.hide||!map||!RT.map)return;const s=[RT.map,px,py,dir].join();if(!force&&s==RT.last&&Date.now()-RT.sentAt<5000)return;RT.last=s;RT.sentAt=Date.now();rtBc(RT.map,'pos',{i:RT.pid,x:px|0,y:py|0,d:dir|0,l:GUEST.look|0})}
function rtMap(id){if(RT.map==id)return;if(RT.map&&RT.on){if(RT.pid&&!RT.hide)rtBc(RT.map,'bye',{i:RT.pid});rtSend(rtTopic(RT.map),'phx_leave',{})}RT.map=id;RT.peers={};if(RT.on){rtJoin(id);setTimeout(()=>rtPos(true),300)}}
async function rtStart(){if(!/^https?:$/.test(location.protocol))return;try{const r=await DB.rpc('presence_claim',{p_tok:mvTok(),p_name:FRIEND?'':(GUEST.name||'')});if(!r||!r.ok)return;RT.pid=r.pid;RT.name=r.name||'';RT.owner=!!r.owner;RT.names[r.pid]={name:r.name||'',owner:!!r.owner};const b=$('#rtBtn');if(b)b.hidden=false;rtBtn();rtConnect();try{const c0=localStorage.getItem('bsw_fr');if(c0)rtFriend(c0)}catch(e){}}catch(e){}}
function rtBtn(){const b=$('#rtBtn');if(!b)return;const n=Date.now(),cnt=Object.values(RT.all).filter(v=>n-v<45000).length+(RT.hide?0:1);b.textContent='👥 '+cnt}
/* 다른 접속자: 같은 칸에 겹치지 않고, 마주 보고 말 걸기 */
function rtTileBusy(x,y){const on=Object.values(RT.peers).some(P=>P.tx==x&&P.ty==y&&Date.now()-(P.seen||0)<14000);if(!on)return false;const k=x+','+y,n=Date.now();if(!RT.bk||RT.bk.k!=k||n-RT.bk.last>400)RT.bk={k,at:n,last:n};RT.bk.last=n;return n-RT.bk.at<1200}
