function tetMv(dx){if(tetFits(TET.p.s,TET.p.x+dx,TET.p.y)){TET.p.x+=dx;tetDraw()}}
function tetRot(){const p=TET.p,s=p.s[0].map((_,i)=>p.s.map(r=>r[i]).reverse());for(const k of[0,-1,1,-2,2])if(tetFits(s,p.x+k,p.y)){p.s=s;p.x+=k;break}tetDraw()}
function tetDown(){if(tetFits(TET.p.s,TET.p.x,TET.p.y+1)){TET.p.y++;TET.score++;tetDraw()}}
function tetDrop(){while(tetFits(TET.p.s,TET.p.x,TET.p.y+1)){TET.p.y++;TET.score+=2}clearTimeout(TET.tm);tetLock();tetDraw();if(TET.run)TET.tm=setTimeout(tetTick,500)}
