function mgSpawn(){if(MG.st!='mole'||!$('#ml0'))return;for(let i=0;i<9;i++)$('#ml'+i).textContent='';const c=Math.random()*9|0,life=Math.max(320,1050-(MG.lv-1)*80);MG.mole=c;$('#ml'+c).textContent='🐹';MG.tm=setTimeout(()=>{if(MG.st!='mole')return;MG.miss++;mgHud();if(MG.miss>=3)return mgEndA(MG.n);mgSpawn()},life)}
