function mgArrow(){const A=$('#mgArena'),B=$('#mgBtn');B.style.display='none';MG.st='arrow';MG.fly=null;MG.stuck=[];MG.n=0;MG.lv=1;MG.left=10;A.innerHTML='<div id="arHud" style="text-align:center;font-weight:bold;margin-bottom:6px"></div><canvas id="arC" width="320" height="170" onpointerdown="event.preventDefault();mgShoot()" style="width:100%;max-width:400px;display:block;margin:0 auto;border-radius:8px;background:#7dd3fc;touch-action:none;cursor:crosshair"></canvas>';MG.a=performance.now();MG.mark=null;const tick=()=>{const c=$('#arC');if(!c||MG.st!='arrow')return;const X=c.getContext('2d'),t=performance.now()-MG.a,tx=160+Math.sin(t/1000*(1+MG.lv*.45))*125;MG.tx=tx;X.clearRect(0,0,320,170);X.fillStyle='#4ade80';X.fillRect(0,130,320,40);[['#f8fafc',30],['#111827',24],['#3b82f6',18],['#ef4444',12],['#fde047',6]].forEach(([k,r])=>{X.fillStyle=k;X.beginPath();X.arc(tx,70,r,0,7);X.fill()});(MG.stuck||[]).forEach(S0=>{const q=performance.now()-S0.a;if(q<2200){X.fillStyle='#78350f';X.fillRect(tx+S0.dx-1,70,2,13);X.fillStyle='#ef4444';X.fillRect(tx+S0.dx-3,82,6,3)}});if(MG.fly){const q=(performance.now()-MG.fly.a)/190,yy=160-q*90,len=26-q*12;X.strokeStyle='#78350f';X.lineWidth=3-q*1.5;X.beginPath();X.moveTo(160,yy);X.lineTo(160,yy+len);X.stroke();X.fillStyle='#475569';X.beginPath();X.moveTo(160,yy-5);X.lineTo(156,yy+2);X.lineTo(164,yy+2);X.fill();X.fillStyle='#ef4444';X.fillRect(157,yy+len-4,6,4);if(q>=1)mgLand()}X.fillStyle='#78350f';X.fillRect(tx-2,100,4,30);X.fillStyle='#111';X.fillRect(158,140,4,22);X.fillRect(150,158,20,3);if(MG.mark&&t-MG.mark.t<700){X.fillStyle='#111';X.font='bold 16px sans-serif';X.textAlign='center';X.fillText(MG.mark.s,160,30);X.textAlign='start'}const h=$('#arHud');if(h)h.textContent='Lv.'+MG.lv+' · '+MG.n+'점 · 남은 화살 '+MG.left;MG.raf=requestAnimationFrame(tick)};tick()}
function mgShoot(){if(MG.st!='arrow'||MG.left<=0||MG.fly)return;MG.left--;MG.fly={a:performance.now()};sfx('s')}
function mgLand(){const d=Math.abs(MG.tx-160),s=d<6?10:d<12?7:d<18?5:d<24?3:d<30?1:0;MG.n+=s*MG.lv;if(s)MG.stuck.push({dx:160-MG.tx,a:performance.now()});if(s>=7)MG.lv++;MG.fly=null;MG.mark={t:performance.now()-MG.a,s:s?(s==10?'명중! +':'+')+s*MG.lv:'빗나갔다'};sfx(s?'w':'b');if(MG.left<=0)setTimeout(()=>mgEndA(MG.n),600)}
const BW_P=[[160,20],[148,34],[172,34],[136,48],[160,48],[184,48],[124,62],[148,62],[172,62],[196,62]];
function mgBowl(){const A=$('#mgArena'),B=$('#mgBtn');B.style.display='none';MG.st='bowl';MG.n=0;MG.fr=1;MG.roll=null;MG.down=[];MG.a=performance.now();MG.mark=null;A.innerHTML='<div id="bwHud" style="text-align:center;font-weight:bold;margin-bottom:6px"></div><canvas id="bwC" width="320" height="170" onpointerdown="event.preventDefault();mgRoll()" style="width:100%;max-width:400px;display:block;margin:0 auto;border-radius:8px;touch-action:none;cursor:pointer"></canvas>';const tick=()=>{const c=$('#bwC');if(!c||MG.st!='bowl')return;const X=c.getContext('2d'),n=performance.now(),t=n-MG.a;let bx,by=152;if(MG.roll){const q=Math.min(1,(n-MG.roll.a)/650);bx=MG.roll.x;by=152-q*140;if(q>=1&&!MG.roll.hit){MG.roll.hit=1;MG.down=MG.roll.pins;MG.mark={t,s:MG.roll.txt};sfx(MG.roll.n?'w':'b')}if(n-MG.roll.a>1500){const R0=MG.roll;MG.n+=R0.n+(R0.n==10?5:0);MG.roll=null;MG.down=[];MG.fr++;if(MG.fr>5)return mgEndA(MG.n)}}else{MG.cx=160+Math.sin(t/1000*(1.6+MG.fr*.5)*(1/bowlBall()[2]))*110;bx=MG.cx}X.fillStyle='#d4a35a';X.fillRect(0,0,320,170);X.fillStyle='#b98a45';for(let i=44;i<280;i+=24)X.fillRect(i,0,2,170);X.fillStyle='#78350f';X.fillRect(0,0,40,170);X.fillRect(280,0,40,170);BW_P.forEach(([x,y],i)=>{if(MG.down.includes(i)){X.fillStyle='#e7e5e4';X.fillRect(x-6,y+2,12,5);X.fillStyle='#ef4444';X.fillRect(x-2,y+2,2,5);return}X.fillStyle='#f8fafc';X.fillRect(x-3,y-6,6,12);X.fillStyle='#ef4444';X.fillRect(x-3,y-3,6,2)});if(!MG.roll||by>12){const r=MG.roll?4+((by-12)/140)*6:10;X.fillStyle=bowlBall()[1];X.beginPath();X.arc(bx,by,r,0,7);X.fill();X.fillStyle='#93c5fd';X.fillRect(bx-2,by-3,2,2)}if(!MG.roll){X.fillStyle='#16a34a';X.fillRect(154,160,12,4)}if(MG.mark&&t-MG.mark.t<900){X.fillStyle='#111';X.font='bold 18px sans-serif';X.textAlign='center';X.fillText(MG.mark.s,160,105);X.textAlign='start'}const h0=$('#bwHud');if(h0)h0.textContent=Math.min(5,MG.fr)+' / 5 프레임 · '+MG.n+'점';MG.raf=requestAnimationFrame(tick)};tick()}
const BALLS=[['8파운드','#ef4444',1.25],['10파운드','#22c55e',1.1],['12파운드','#1e3a8a',1],['14파운드','#7c3aed',.85]];
const bowlBall=()=>{try{return BALLS[+localStorage.getItem('bsw_ball')||2]||BALLS[2]}catch(e){return BALLS[2]}};
function showBowlBalls(){openM('<h3>🎳 공 고르기</h3><p style="font-size:12px;opacity:.8">가벼울수록 표시가 빨라 어렵고, 무거울수록 느려서 맞추기 쉬워요.</p><div class="xcol">'+BALLS.map((b,i)=>'<button class="xb big" onclick="bowlPick('+i+')"><span style="display:inline-block;width:14px;height:14px;border-radius:50%;background:'+b[1]+';vertical-align:-2px"></span> '+b[0]+(bowlBall()==b?' ✓':'')+'</button>').join('')+'</div>')}
function bowlPick(i){try{localStorage.setItem('bsw_ball',i)}catch(e){}closeM();toast(BALLS[i][0]+' 공을 골랐어요. 🎳')}
function showBowlShop(){const own=()=>{try{return JSON.parse(localStorage.getItem('bsw_bowl_own'))||[]}catch(e){return[]}},O=own(),I=[['🎳','내 볼링공'],['👟','볼링화'],['🧤','볼링 장갑'],['🎒','볼링 가방']];openM('<h3>🛒 볼링 장비 가게</h3><p style="font-size:12px;opacity:.8">놀이용이라 돈은 들지 않아요. 산 물건은 이 기기에 저장돼요.</p><div class="xcol">'+I.map((x,i)=>'<button class="xb big" onclick="bowlBuy('+i+')">'+x[0]+' '+esc(x[1])+(O.includes(i)?' ✓ 보유':'')+'</button>').join('')+'</div><div class="qbtn"><button class="xb" onclick="showBowlBalls()">공 무게 고르기</button></div>')}
function bowlBuy(i){let O=[];try{O=JSON.parse(localStorage.getItem('bsw_bowl_own'))||[]}catch(e){}if(!O.includes(i)){O.push(i);try{localStorage.setItem('bsw_bowl_own',JSON.stringify(O))}catch(e){}toast('샀어요! 🛍')}showBowlShop()}
function mgRoll(){if(MG.st!='bowl'||MG.roll||MG.fr>5)return;const x=MG.cx,d=Math.abs(x-160),hit=d<6?10:d<16?7+(Math.random()*3|0):d<40?3+(Math.random()*4|0):d<70?Math.random()*3|0:0,order=BW_P.map((p,i)=>[Math.abs(p[0]-x)+Math.random()*12,i]).sort((a,b)=>a[0]-b[0]).map(e=>e[1]);MG.roll={a:performance.now(),x,n:hit,pins:order.slice(0,hit),txt:hit==10?'스트라이크! +15':hit?hit+'개!':'거터…'};sfx('w')}
function mgEndA(v){const g=MG.g;cancelAnimationFrame(MG.raf);clearTimeout(MG.tm);const A=$('#mgArena'),B=$('#mgBtn');if(A)A.innerHTML='';if(B)B.style.display='';if(!v){MG.st='idle';if(B){B.style.background='#1e293b';B.textContent='다시 하기'}const R0=$('#mgRes');if(R0)R0.textContent='0점이에요. 다시 해 봐요!';return}mgDone(v)}
function mgPress(){const b=$('#mgBtn');if(MG.st=='gun')return mgFire();if(MG.st=='arrow')return mgShoot();if(MG.st=='bowl')return mgRoll();if(!b)return;const g=MG.g,G=MG_G[g],now=performance.now();if(G.arena&&(MG.st=='idle'||MG.st=='done')){const s=$('#mgSave');if(s)s.hidden=true;const R0=$('#mgRes');if(R0)R0.textContent='';return g=='mole'?mgMole():g=='bowl'?mgBowl():g=='gun'?mgGun():mgArrow()}
  if(MG.st=='idle'||MG.st=='done'){const s=$('#mgSave');if(s)s.hidden=true;const R=$('#mgRes');if(R)R.textContent='';
    if(G.t){MG.st='run';MG.a=now;b.style.background='#7c3aed';const tick=()=>{if(MG.st!='run'||!$('#mgBtn'))return;const e=performance.now()-MG.a;b.textContent=e<1000?(e/1000).toFixed(2)+'초':'? ? ?  멈춰!';MG.raf=requestAnimationFrame(tick)};tick()}
    else if(g=='react'){MG.st='wait';b.style.background='#b91c1c';b.textContent='기다리세요…';MG.tm=setTimeout(()=>{MG.st='go';MG.a=performance.now();const B=$('#mgBtn');if(B){B.style.background='#16a34a';B.textContent='지금!'}},1200+Math.random()*3000)}
    else{MG.st='tap';MG.n=0;MG.a=now;b.style.background='#ea580c';b.textContent='누르세요!';const tick=()=>{if(MG.st!='tap'||!$('#mgBtn'))return;const left=10000-(performance.now()-MG.a);if(left<=0)return mgDone(MG.n);b.textContent=MG.n+'회 · '+(left/1000).toFixed(1)+'초';MG.raf=requestAnimationFrame(tick)};tick()}
    return}
  if(MG.st=='run'){const e=Math.round(now-MG.a),R=$('#mgRes');mgDone(Math.abs(e-G.t));if(R)R.innerHTML+='<br><small>'+(e/1000).toFixed(3)+'초에 멈췄어요</small>';return}
  if(MG.st=='wait'){mgStop();MG.st='idle';b.style.background='#1e293b';b.textContent='너무 빨랐어요! 다시';return}
  if(MG.st=='go'){return mgDone(Math.round(now-MG.a))}
  if(MG.st=='tap'){MG.n++}}
document.addEventListener('keydown',e=>{if(e.code!='Space'&&e.key!=' ')return;if(!$('#mgBtn')||e.repeat)return;const t=e.target;if(t&&/INPUT|TEXTAREA/.test(t.tagName))return;e.preventDefault();e.stopPropagation();mgPress()},true);
const RANK_W={18:Object.keys(AG_G),1:['sec3','sec5','sec7','sec10'],2:['react','tap'],3:['mole'],4:['arrow'],6:['gun'],7:['claw'],8:['tetris']};
function showRankWall(x,sel){const L=RANK_W[x];if(!L)return;const g0=sel||L[0],nm=k=>AG_G[k]?AG_G[k].ic+' '+AG_G[k].n:k=='claw'?'🧸 인형뽑기':k=='tetris'?'🧱 테트리스':MG_G[k].ic+' '+MG_G[k].n;openM('<h3>🏆 오락실 순위</h3><div class="qbtn" style="justify-content:flex-start">'+L.map(k=>`<button class="xb" style="${k==g0?'background:#2563eb;color:#fff':''}" onclick="showRankWall(${x},'${k}')">${esc(nm(k))}</button>`).join('')+'</div><div id="rkW" style="margin-top:8px"><small>불러오는 중…</small></div>');(async()=>{let H0='';try{if(g0=='claw'){const R0=await DB.rpc('claw_top');H0=R0.map((r,i)=>`<div class="xrow" style="margin:2px 0;padding:4px 8px"><span>${i+1}. ${esc(r.name)}</span><b>${Number(r.tries)}회 · ${Number(r.wins)}성공 · ${Number(r.rate)}%</b></div>`).join('')}else if(g0=='tetris'){const R0=await DB.rpc('tetris_top');H0=R0.map((r,i)=>`<div class="xrow" style="margin:2px 0;padding:4px 8px"><span>${i+1}. ${esc(r.name)}</span><b>${Number(r.score).toLocaleString('ko-KR')}</b></div>`).join('')}else{const R0=await DB.rpc('arcade_top',{p_game:g0});H0=R0.map((r,i)=>`<div class="xrow" style="margin:2px 0;padding:4px 8px"><span>${i+1}. ${esc(r.name)}</span><b>${esc(mgFmt(g0,r.val))}</b></div>`).join('')}}catch(e){H0='<small>순위를 불러오지 못했어요.</small>'}const E0=$('#rkW');if(E0)E0.innerHTML=H0||'<small>아직 기록이 없어요.</small>'})()}
async function mgRank(){const g=MG.g,el=$('#mgRank');if(!el)return;try{const L=await DB.rpc('arcade_top',{p_game:g});if(MG.g!=g||!$('#mgRank'))return;$('#mgRank').innerHTML=L.length?L.map((r,i)=>`<div class="xrow" style="margin:2px 0;padding:3px 8px"><span>${i+1}. ${esc(r.name)}</span><b>${esc(mgFmt(g,r.val))}</b></div>`).join(''):'<small style="opacity:.7">아직 기록이 없어요. 첫 번째가 되어 보세요!</small>'}catch(e){const E=$('#mgRank');if(E)E.innerHTML='<small style="opacity:.7">순위 서버 준비 중이에요. 내 최고 기록은 이 기기에 저장돼요.</small>'}}
async function mgSend(){if(MG.val==null)return;const i=$('#mgName'),n=(i&&i.value||'').trim();if(!n)return toast('이름을 적어 주세요.');try{localStorage.setItem('bsw_mg_name',n)}catch(e){}try{const r=await DB.rpc('arcade_add',{p_game:MG.g,p_name:n,p_val:MG.val});if(!r||!r.ok)return toast(r&&r.err=='busy'?'잠시 뒤에 다시 등록해 주세요.':'기록을 등록하지 못했어요.');MG.val=null;const s=$('#mgSave');if(s)s.hidden=true;toast('순위에 등록했어요! 🏆');mgRank()}catch(e){toast('순위 서버 준비 중이에요.')}}
async function tetRank(){
  const el=$('#tRank');if(!el)return;
  try{const L=await DB.rpc('tetris_top');el.innerHTML=L.length?L.map((r,i)=>`<div class="xrow" style="margin:2px 0;padding:3px 8px"><span>${i+1}. ${esc(r.name)}</span><b>${Number(r.score).toLocaleString('ko-KR')}</b></div>`).join(''):'<small style="opacity:.7">아직 기록이 없어요. 1등 해 보세요!</small>'}
  catch(e){el.innerHTML=`<small style="opacity:.7">${esc(dbErr(e))}</small>`}
}
/* 게임 오버 기록은 버튼을 안 눌러도 남습니다: 이름을 저장해 뒀으면 바로, 아니면 나가거나 다시 시작할 때 '익명'으로 */
async function tetSave(){
  const P=TET.pend;if(!P)return;TET.pend=null;
  const e0=$('#tName'),n=e0?e0.value.trim():'',m=$('#tRes');
  try{const r=await DB.rpc('tetris_add',{p_name:n,p_score:P.s,p_lines:P.l});
    if(!r.ok){if(m)m.textContent='기록을 남기지 못했어요: '+(r.err=='rate'?'지금 기록이 너무 많아요. 잠시 후 다시 해 주세요.':'저장할 수 없는 기록이에요.');if(r.err=='rate'){TET.pend=P}return toast(r.err=='rate'?'지금 기록이 너무 많아요. 잠시 후 다시 해 주세요.':'저장할 수 없는 기록이에요.')}
    if(n)try{localStorage.setItem('bsw_tname',n)}catch(e){}
    const v=$('#tSave');if(v)v.hidden=true;if(m)m.textContent='게임 오버! '+P.s.toLocaleString('ko-KR')+'점 · '+(n||'익명')+' 이름으로 등록했어요 🏆';toast('순위에 등록했어요! 🏆');tetRank();
  }catch(e){TET.pend=P;if(m)m.textContent='기록을 남기지 못했어요: '+dbErr(e);toast(dbErr(e))}
}
function showTetris(){
  openM(`<h3>🎮 테트리스</h3>
  <div style="display:flex;gap:10px;justify-content:center">
    <canvas id="tc" width="${TW*TC}" height="${TH*TC}" style="border:2px solid #fbbf24;border-radius:4px;flex:none"></canvas>
    <div style="font-size:12px;min-width:92px"><b>다음</b><br><canvas id="tn" width="64" height="44" style="border:1px solid var(--bd);margin:3px 0 8px"></canvas><br>
    점수 <b id="ts">0</b><br>줄 <b id="tl">0</b><br>레벨 <b id="tv">1</b>
    <p style="font-size:10px;opacity:.8;margin-top:8px;line-height:1.5">←→ 이동<br>↑ / Z·A 회전<br>↓ 천천히<br>Space·패드▲ 한번에<br>X·B 나가기</p></div>
  </div>
  <div class="qbtn" style="justify-content:center"><button class="xb" id="tStart" onclick="tetStart()">▶ 시작</button></div>
  <div id="tOver" hidden style="margin-top:8px;text-align:center"><b id="tRes"></b><div id="tSave" style="margin-top:6px"><input id="tName" class="xin" maxlength="12" placeholder="순위에 남길 이름" onkeydown="if(event.key=='Enter'){event.stopPropagation();tetSave()}"><div class="qbtn" style="justify-content:center"><button class="xb" onclick="tetSave()">🏆 순위 등록</button></div></div></div>
  <div class="qform" style="margin-top:8px"><b>🏆 순위 TOP 10</b><div id="tRank" style="margin-top:4px"><small>불러오는 중…</small></div></div>`);
  TET.b=Array.from({length:TH},()=>Array(TW).fill(0));TET.score=0;TET.lines=0;TET.lvl=1;TET.nx=null;tetDraw();tetRank();
}

