/* BS WORLD 게시판: 칸마다 전단지가 붙어 있고, 누르면 크게 봄. 운영자는 여기서 올리고 지움 */
let BOARD=null;const bdUrl=p=>/^p\//.test(p)?DBCFG.url+'/storage/v1/object/public/board/'+p:p;
async function showBoard(){let L=ADS.map((a,i)=>({...a,id:null}));try{const r=await DB.rpc('board_list');if(Array.isArray(r)&&r.length)L=r;else if(Array.isArray(r))L=[]}catch(e){}BOARD=L;boardDraw()}
function boardDraw(){const L=BOARD||[],n=Math.max(2,Math.ceil(L.length/2)*2),cells=[];for(let i=0;i<n;i++){const a=L[i];cells.push(a?`<button class="bdc" onclick="boardOpen(${i})" title="${esc(a.title)}"><img src="${esc(bdUrl(a.img))}" alt="${esc(a.title)}" loading="lazy"></button>`:'<div class="bdc bde"></div>')}
 openM(`<div class="bdw"><div class="bdh">BS WORLD 게시판</div><div class="bdg">${cells.join('')}</div></div><p class="adhint" style="margin-top:8px">전단지를 누르면 크게 볼 수 있어요${L.length>2?' · 아래로 내리면 더 있어요':''}</p>`+(isOwner()?`<div class="qform"><b>📤 운영자 전단지 올리기</b><input id="bdF" type="file" accept="image/*" class="xin" style="margin-top:6px"><input id="bdT" class="xin" maxlength="40" placeholder="제목 (예: 🥝 제주산 골드키위)"><input id="bdL" class="xin" maxlength="200" placeholder="연결 주소 (https://… 또는 tel:010…, 없어도 돼요)"><input id="bdB" class="xin" maxlength="30" placeholder="버튼 글씨 (예: 📞 전화로 문의하기)"><div class="qbtn"><button class="xb big" onclick="boardUp()">올리기</button></div><p id="bdM" style="font-size:12px;opacity:.8"></p></div>`:''))}
function boardOpen(i){const a=BOARD[i];if(!a)return;openM(`<h3>${esc(a.title)}</h3><img class="adimg" src="${esc(bdUrl(a.img))}" alt="${esc(a.title)}" title="눌러서 더 크게 보기" onclick="lbOpen(this.src,this.alt)"><p class="adhint">🔍 한 번 더 누르면 더 크게 볼 수 있어요</p><div class="adbtn">${a.link?`<a class="xb" href="${esc(a.link)}" target="_blank" rel="noopener">${esc(a.btn||'자세히 보기')}</a> `:''}<button class="xb" onclick="boardDraw()">← 게시판으로</button>${isOwner()&&a.id?` <button class="xb" onclick="boardDel(${a.id})">🗑 지우기</button>`:''}</div>`)}
async function bdShrink(F){const im=await createImageBitmap(F),S0=Math.min(1,2000/Math.max(im.width,im.height)),c=document.createElement('canvas');c.width=im.width*S0|0;c.height=im.height*S0|0;c.getContext('2d').drawImage(im,0,0,c.width,c.height);return new Promise(ok=>c.toBlob(ok,'image/jpeg',.88))}
async function boardUp(){const F=$('#bdF').files[0],m=$('#bdM');if(!F)return toast('사진을 골라 주세요.');try{m.textContent='올리는 중…';const blob=await bdShrink(F),a=new Uint8Array(16);crypto.getRandomValues(a);const path='p/'+[...a].map(b=>b.toString(16).padStart(2,'0')).join('')+'.jpg',up=await fetch(DBCFG.url+'/storage/v1/object/board/'+path,{method:'POST',body:blob,headers:{apikey:DBCFG.key,Authorization:'Bearer '+DB.tok,'Content-Type':'image/jpeg'}});if(!up.ok)throw new Error('upload');const L0=$('#bdL').value.trim(),r=await DB.rpc('board_add',{p_title:$('#bdT').value,p_img:path,p_link:L0||null,p_btn:$('#bdB').value});if(!r||!r.ok){await fetch(DBCFG.url+'/storage/v1/object/board/'+path,{method:'DELETE',headers:{apikey:DBCFG.key,Authorization:'Bearer '+DB.tok}});m.textContent=r&&r.err=='link'?'연결 주소는 https:// 또는 tel: 로 시작해야 해요.':'올리지 못했어요.';return}toast('📌 게시판에 붙였어요.');showBoard()}catch(e){m.textContent='올리지 못했어요. 게시판 SQL을 실행했는지 확인해 주세요.'}}
async function boardDel(id){try{const r=await DB.rpc('board_del',{p_id:id});if(r&&r.ok){if(r.img&&/^p\//.test(r.img))await fetch(DBCFG.url+'/storage/v1/object/board/'+r.img,{method:'DELETE',headers:{apikey:DBCFG.key,Authorization:'Bearer '+DB.tok}});toast('🗑 지웠어요.');showBoard()}else toast('지우지 못했어요.')}catch(e){toast('지우지 못했어요.')}}

