function blob(cx,cy,rx,ry,sd){
  const n=20,p=[];for(let i=0;i<n;i++){const a=i/n*Math.PI*2,j=1+.07*Math.sin(a*3+sd)+.04*Math.sin(a*5+sd*2);p.push([cx+Math.cos(a)*rx*j,cy+Math.sin(a)*ry*j])}
  const m=(a,b)=>[(a[0]+b[0])/2,(a[1]+b[1])/2],f=v=>v.map(q=>q.toFixed(1)).join(' ');
  let d='M'+f(m(p[n-1],p[0]));for(let i=0;i<n;i++)d+=' Q'+f(p[i])+' '+f(m(p[i],p[(i+1)%n]));return d+'Z';
}
