function press(d){if(modal&&TET.run)return tetPad(d);if(modal&&lbOn())return lbScroll(d);if(modal)return kcMove(d==1||d==2?-1:1);if(dlg&&dlg.s=='m'){dlg.sel=(dlg.sel+(d==1?-1:d==0?1:0)+dlg.keys.length)%dlg.keys.length;menu()}else held=d}
const inputReset=()=>{held=null};addEventListener('blur',inputReset);document.addEventListener('visibilitychange',()=>{if(document.hidden)held=null});addEventListener('pagehide',inputReset);
const KM={ArrowDown:0,s:0,ArrowUp:1,w:1,ArrowLeft:2,a:2,ArrowRight:3,d:3};

addEventListener('keydown',e=>{
  if(modal)return kcKey(e);
  if(!e.repeat){const tk={ArrowUp:'u',w:'u',ArrowDown:'d',s:'d',ArrowLeft:'l',ArrowRight:'r',d:'r',x:'b',X:'b',b:'b',z:'a',Z:'a'}[e.key];if(tk)kcode(tk)}
  if(e.target&&/^(INPUT|TEXTAREA|SELECT)$/.test(e.target.tagName))return;   // 입력 중에는 게임 키 무시
  const st = $('#st');
  const isStarted = st && st.style.display === 'none';

  if (!isStarted) {
    if ([' ', 'Enter', 'z', 'Z'].includes(e.key)) {
      e.preventDefault();
      startGame();
      return;
    }
  }

  if(['m','M'].includes(e.key)&&PV.p&&PV.bg)return plToggle();
  if(['n','N'].includes(e.key)&&(PV.bg||SB.on))return bgmNext();
  const k=KM[e.key];
  if(k!=null){
    e.preventDefault();
    if(!e.repeat||!dlg) press(k);
    return;
  }
  if(['z','Z','Enter',' '].includes(e.key)){
    e.preventDefault();
    act();
  }
  if(['x','X','Escape'].includes(e.key)) cancel();
});

addEventListener('keyup',e=>{const k=KM[e.key];if(k!=null&&held===k)held=null});

document.querySelectorAll('.dp button').forEach(b=>{const d=+b.dataset.d;b.addEventListener('pointerdown',e=>{e.preventDefault();if(!modal)kcode('dulr'[d]);press(d)});['pointerup','pointerleave','pointercancel'].forEach(t=>b.addEventListener(t,()=>{if(held===d)held=null}))});
$('#bA').addEventListener('pointerdown',e=>{e.preventDefault();if(!modal)kcode('a');act()});$('#bB').addEventListener('pointerdown',e=>{e.preventDefault();if(!modal)kcode('b');cancel()});

